import{_ as a,o as l,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"The Challenge of Storing Small Objects on a Large Scale - Luis Domingues & Ján Senko, Proton AG","description":"","frontmatter":{"title":"The Challenge of Storing Small Objects on a Large Scale - Luis Domingues & Ján Senko, Proton AG","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Small Objects Optimization","Storage Efficiency","Data Recovery"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/The_Challenge_of_Storing_Small_Objects_on_a_Large_Scale_-_Luis_Domingues_Jan_Senko_Proton_AG.md","filePath":"posts/2025/The_Challenge_of_Storing_Small_Objects_on_a_Large_Scale_-_Luis_Domingues_Jan_Senko_Proton_AG.md","lastUpdated":1780459816000}'),i={name:"posts/2025/The_Challenge_of_Storing_Small_Objects_on_a_Large_Scale_-_Luis_Domingues_Jan_Senko_Proton_AG.md"};function n(r,e,s,_,h,u){return l(),o("div",null,[...e[0]||(e[0]=[t('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>Proton 公司作为一家总部位于日内瓦的互联网服务提供商，在2018年选择了 Ceph 作为其分布式存储解决方案，以应对快速增长的数据存储需求。以下是对其 Ceph 存储系统发展历程与挑战的详细总结：</p><h3 id="历史背景" tabindex="-1">历史背景 <a class="header-anchor" href="#历史背景" aria-label="Permalink to &quot;历史背景&quot;">​</a></h3><ul><li>2018年，Proton 开始使用 Ceph 解决其数据存储问题。</li><li>初始集群由8台服务器组成，每台服务器配备12块HDD，总容量为1PB。</li><li>使用Erasure Coding 4+2策略和双数据中心镜像，存储成本降低至3倍。</li></ul><h3 id="面临的挑战" tabindex="-1">面临的挑战 <a class="header-anchor" href="#面临的挑战" aria-label="Permalink to &quot;面临的挑战&quot;">​</a></h3><ul><li><strong>小对象问题</strong>：由于电子邮件头部信息占用大量空间，导致存储效率低下。</li><li><strong>恢复时间过长</strong>：HDD的随机读写性能差，导致磁盘故障后恢复时间长。</li><li><strong>OMAP性能问题</strong>：随着数据量增加，OMAP的更新和恢复操作变得缓慢。</li></ul><h3 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h3><ul><li><strong>Multi Blob</strong>：将多个小对象合并为大对象，以提高恢复效率。</li><li><strong>OMAP优化</strong>：减少OMAP的更新频率，提升性能。</li><li><strong>SSD使用</strong>：考虑使用SSD存储小对象，但成本问题限制了实施。</li></ul><h3 id="部署工具" tabindex="-1">部署工具 <a class="header-anchor" href="#部署工具" aria-label="Permalink to &quot;部署工具&quot;">​</a></h3><ul><li><strong>初始工具</strong>：使用Sible进行集群管理，但随着集群规模扩大，部署时间过长。</li><li><strong>Ceph ADM</strong>：用于较小的内部集群，管理RBD和S3服务。</li><li><strong>Rook</strong>：基于Kubernetes进行自动化部署，用于用户数据集群。</li></ul><h3 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h3><ul><li>每个集群存储30PB用户数据，总存储量接近100PB。</li><li>小对象问题仍存，但已通过优化减少影响。</li><li>MClock调度算法表现更好，减少了调优工作。</li></ul><h3 id="未来发展" tabindex="-1">未来发展 <a class="header-anchor" href="#未来发展" aria-label="Permalink to &quot;未来发展&quot;">​</a></h3><ul><li>从4+2 Erasure Coding升级到8+3。</li><li>关注Ceph新版本的小对象优化功能。</li><li>预计未来存储需求将增长10倍，达到Exabyte级别。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>升级Erasure Coding策略。</li><li>测试Ceph新版本的小对象优化功能。</li><li>继续优化OMAP和Multi Blob解决方案。</li><li>探索Kubernetes和Rook的进一步应用。</li></ul><p>通过这些解决方案和策略，Proton成功地使用Ceph应对了快速增长的存储需求，并逐步提升了存储系统的稳定性和效率。</p>',17)])])}const d=a(i,[["render",n]]);export{c as __pageData,d as default};
